const PLAIN_FIXTURE_PROFILE_ID = 'plain-fixture';

const fixtureLocalTarget: LocalEngineTarget = { kind: 'uds', path: '/tmp/ua-elr14-fixture.sock' };

function plainFixtureIdentity(): IClientIdentityStore {
	const identity = {
		clientIdentityId: 'b'.repeat(64),
		clientPublicKey: new Uint8Array(32),
		privateKeyPkcs8: new Uint8Array(32),
	};
	return {
		getState: async () => ({ kind: 'ready', identity }),
		getOrCreateIdentity: async () => ({ kind: 'ready', identity }),
		createSigner: async () => undefined,
	};
}

function plainFixtureResolver(): ConnectionResolver {
	return {
		resolve: async () => ({
			ok: true as const,
			allowRelayFallback: false as const,
			endpoint: {
				attemptId: 'plain-fixture',
				authority: '127.0.0.1:9',
				port: 9,
				resolvedIp: '127.0.0.1',
				servername: '127.0.0.1',
				relayTicketId: null,
				tls: null,
				expiresAtMs: Date.now() + 60_000,
				path: 'direct' as const,
			},
		}),
		consumeRelayTicket: () => { },
	} as unknown as ConnectionResolver;
}

async function connectPlainFixture(service: UniverseAgentConnectionService): Promise<void> {
	const result = await service.connectProfile(PLAIN_FIXTURE_PROFILE_ID);
	if (!result.ok) {
		throw new Error(`${result.code}: ${result.reason}`);
	}
}

function localEngineFixtureOptions(
	transport: MockUniverseAgentGrpcTransport,
	override: Partial<UniverseAgentConnectionServiceOptions> = {},
): UniverseAgentConnectionServiceOptions {
	return {
		autoConnectLocalEngine: true,
		storageReady: Promise.resolve(),
		findLocalEngine: async () => fixtureLocalTarget,
		openLocalEngineTransport: () => transport as unknown as GrpcUniverseAgentClient,
		setTimeoutFn: callback => {
			queueMicrotask(callback);
			return 0 as unknown as ReturnType<typeof setTimeout>;
		},
		clearTimeoutFn: () => { },
		reconnectJitterRatio: 0,
		...override,
	};
}

async function settleLocalTurns(): Promise<void> {
	for (let i = 0; i < 30; i++) {
		await new Promise(resolve => setImmediate(resolve));
	}
}

async function waitForLocalFixture(service: UniverseAgentConnectionService): Promise<void> {
	for (let i = 0; i < 40; i++) {
		await new Promise(resolve => setImmediate(resolve));
		if (service.getConnectionPhase().kind === 'connected') {
			return;
		}
	}
	throw new Error(`local fixture did not connect: ${service.getConnectionPhase().kind}`);
}

suite('UniverseAgentConnectionService', () => {

	const store = ensureNoDisposablesAreLeakedInTestSuite();

	test('token + live channel => isEngineConnected === true', async () => {
		const transport = new MockUniverseAgentGrpcTransport();
		const service = new UniverseAgentConnectionService({
			connectionResolver: plainFixtureResolver(),
			clientIdentityStore: plainFixtureIdentity(),
			createTransport: () => transport,
		});

		await connectPlainFixture(service);

		assert.strictEqual(service.isEngineConnected(), true);
		assert.strictEqual(service.getTransportState(), 'ok');
		assert.strictEqual((service as unknown as { _sessionToken?: string })._sessionToken, 'token-1');
		assert.strictEqual(service.getConnectionSnapshot().authenticated, true);
		assert.strictEqual(Object.hasOwn(service.getConnectionSnapshot(), 'sessionToken'), false);
		service.dispose();
	});

	test('a stale AgentService.Tree result does not write the new transport\'s probe state', async () => {
		const treeNodeA = {
			agentId: 'a-root',
			name: 'Root A',
			type: 'AGENT_TYPE_ROOT',
			status: 'AGENT_STATUS_IDLE',
			model: '',
			turnCount: 0,
			createdAt: 0,
			children: [],
		};
		let releaseA!: () => void;
		const treeOnA = new Promise<typeof treeNodeA>(resolve => { releaseA = () => resolve(treeNodeA); });
		const transportA = new MockUniverseAgentGrpcTransport({
			connect: async () => ({
				sessionToken: 'token-a',
				methods: ['AgentService.Tree'],
				events: [],
			}),
			probeRpc: async () => GrpcStatusCode.OK,
			fetchAgentTree: async () => treeOnA,
		});
		const transportB = new MockUniverseAgentGrpcTransport({
			connect: async () => ({
				sessionToken: 'token-b',
				methods: ['AgentService.Tree'],
				events: [],
			}),
			probeRpc: async () => GrpcStatusCode.OK,
			fetchAgentTree: async () => undefined,
		});

		let transportIndex = 0;
		const transports = [transportA, transportB];
		const service = new UniverseAgentConnectionService({
			connectionResolver: {
				resolve: async (profileId: string) => ({
					ok: true as const,
					allowRelayFallback: false as const,
					endpoint: {
						attemptId: `endpoint-${profileId}`,
						authority: '127.0.0.1:9',
						port: 9,
						resolvedIp: '127.0.0.1',
						servername: '127.0.0.1',
						relayTicketId: null,
						tls: null,
						expiresAtMs: Date.now() + 60_000,
						path: 'direct' as const,
					},
				}),
				consumeRelayTicket: () => { },
			} as unknown as ConnectionResolver,
			clientIdentityStore: plainFixtureIdentity(),
			createTransport: () => transports[transportIndex++],
		});

		assert.strictEqual((await service.connectProfile('profile-a')).ok, true);
		const pendingA = service.fetchAgentTree('s1');
		// Let A's call reach the transport before switching links.
		await Promise.resolve();
		assert.strictEqual((await service.connectProfile('profile-b')).ok, true);
		const capabilityOnB = service.getCapabilitySnapshot().agentTree.support;

		releaseA();
		assert.strictEqual(await pendingA, undefined, 'a stale tree must not be returned to the caller');
		assert.strictEqual(service.isAgentTreeUnsupported(), false);
		assert.strictEqual(service.isAgentTreeFetchFailed(), false);
		assert.strictEqual(service.getCapabilitySnapshot().agentTree.support, capabilityOnB);

		service.dispose();
	});

	test('successful unary after DEADLINE_EXCEEDED restores connected phase', async () => {
		let failOnce = true;
		const transport = new MockUniverseAgentGrpcTransport({
			listSessions: async () => {
				if (failOnce) {
					failOnce = false;
					throw new UniverseAgentTransportError(GrpcStatusCode.DEADLINE_EXCEEDED, 'deadline');
				}
				return { sessions: [], totalCount: 0 };
			},
		});
		const service = new UniverseAgentConnectionService({
			connectionResolver: plainFixtureResolver(),
			clientIdentityStore: plainFixtureIdentity(),
			createTransport: () => transport,
		});
		await connectPlainFixture(service);
		(service as unknown as { _activeProfileId: string })._activeProfileId = 'p1';
		await assert.rejects(() => service.listSessions({}));
		assert.strictEqual(service.getConnectionPhase().kind, 'connecting');
		assert.strictEqual((service.getConnectionPhase() as { reason?: string }).reason, 'transport_lost');
		await service.listSessions({});
		assert.strictEqual(service.getConnectionPhase().kind, 'connected');
		service.dispose();
	});

	test('subscribeSessionEventStream forwards transport onClosed', async () => {
		const transport = new MockUniverseAgentGrpcTransport();
		const service = new UniverseAgentConnectionService({
			connectionResolver: plainFixtureResolver(),
			clientIdentityStore: plainFixtureIdentity(),
			createTransport: () => transport,
		});
		await connectPlainFixture(service);

		const seen: UniverseAgentSessionStreamCloseCause[] = [];
		service.subscribeSessionEventStream('sess-1', () => { }, cause => seen.push(cause));
		transport.fireSessionStreamClosed({ kind: 'remote' });
		transport.fireSessionStreamClosed({ kind: 'error', message: 'late' });
		assert.deepStrictEqual(seen, [{ kind: 'remote' }]);
		service.dispose();
	});

