	test('repainting a pending confirmation after Allow stays disabled', () => {
		const decisions: string[] = [];
		const renderer = renderSeat((_turnId, status) => decisions.push(status));
		const container = document.createElement('div');
		const pending: ConversationStubTurn = { id: 'c1', kind: 'confirmation', text: 'Run the tool?', status: 'pending' };
		const template = renderer.renderTemplate(container);
		renderer.renderElement(node(pending), 0, template);
		const firstAllow = container.querySelector('.conversation-lens-confirmation-actions .monaco-button') as HTMLElement;
		firstAllow.click();
		assert.deepStrictEqual(decisions, ['allowed']);

		renderer.renderElement(node({ ...pending }), 0, template);
		const buttons = [...container.querySelectorAll('.conversation-lens-confirmation-actions .monaco-button')] as HTMLElement[];
		assert.strictEqual(buttons.length, 2);
		assert.strictEqual(container.querySelector('.conversation-lens-confirmation-seat')?.getAttribute('aria-busy'), 'true');
		buttons[0].click();
		buttons[1].click();
		assert.deepStrictEqual(decisions, ['allowed']);

		renderer.renderElement(node({ ...pending, respondFailure: { retryable: true, error: 'ipc closed' } }), 0, template);
		const retry = container.querySelector('.conversation-lens-confirmation-actions .monaco-button') as HTMLElement;
		assert.strictEqual(retry.getAttribute('aria-disabled'), 'false');
		retry.click();
		assert.deepStrictEqual(decisions, ['allowed', 'allowed']);
		template.disposables.dispose();
	});

	test('repainting a pending question after Submit stays disabled until a failure', () => {
		const responded: string[] = [];
		const renderer = renderSeat(() => { }, turnId => responded.push(turnId));
		const container = document.createElement('div');
		const pending: ConversationStubTurn = {
			id: 'q1',
			kind: 'question',
			text: 'Pick one',
			status: 'pending',
			questionItems: [{ id: 'item', title: 'Choice', options: ['alpha'] }],
			answerKeysValid: true,
			questionRequestId: 'req-1',
		};
		const template = renderer.renderTemplate(container);
		renderer.renderElement(node(pending), 0, template);
		const radio = container.querySelector('[role="radio"]') as HTMLElement;
		radio.click();
		assert.deepStrictEqual(responded, ['q1']);

		renderer.renderElement(node({ ...pending, questionItems: pending.questionItems?.map(item => ({ ...item })) }), 0, template);
		const again = container.querySelector('[role="radio"]') as HTMLElement;
		assert.strictEqual(container.querySelector('.conversation-lens-question-seat')?.getAttribute('aria-busy'), 'true');
		again.click();
		assert.deepStrictEqual(responded, ['q1']);

		renderer.renderElement(node({ ...pending, respondFailure: { retryable: true, error: 'ipc closed' } }), 0, template);
		const retry = container.querySelector('[role="radio"]') as HTMLElement;
		assert.notStrictEqual(container.querySelector('.conversation-lens-question-seat')?.getAttribute('aria-busy'), 'true');
		retry.click();
		assert.deepStrictEqual(responded, ['q1', 'q1']);
		template.disposables.dispose();
	});

	test('repainting a respondable client tool stays disabled until a retryable failure', () => {
		const responded: string[] = [];
		const renderer = renderSeat(() => { }, undefined, turn => responded.push(turn.id));
		const container = document.createElement('div');
		const pending: ConversationStubTurn = {
			id: 'client-call', kind: 'tool', text: 'Pick a file', toolName: 'clientPick', toolStatus: 'pending', respondable: true,
		};
		const template = renderer.renderTemplate(container);
		const renderFold = (turn: ConversationStubTurn) => {
			const span = projectProcessFoldSpans([turn])[0];
			assert.ok(span);
			renderer.ensureProcessFoldExpanded(span.id);
			renderer.renderElement({ ...node(turn), element: { variant: 'process-fold', turn, processFoldSpan: span } }, 0, template);
		};
		renderFold(pending);
		const first = container.querySelector<HTMLButtonElement>('.conversation-process-fold-tool-respond');
		assert.ok(first, 'the formal process fold must render the client-tool response CTA');
		first.click();
		assert.deepStrictEqual(responded, ['client-call']);

		renderFold({ ...pending });
		const held = container.querySelector<HTMLButtonElement>('.conversation-process-fold-tool-respond');
		assert.ok(held);
		assert.strictEqual(held.disabled, true);
		assert.strictEqual(held.getAttribute('aria-busy'), 'true');
		held.click();
		assert.deepStrictEqual(responded, ['client-call']);

		renderFold({ ...pending, respondFailure: { retryable: true, error: 'ipc closed' } });
		const retry = container.querySelector<HTMLButtonElement>('.conversation-process-fold-tool-respond');
		assert.ok(retry);
		assert.strictEqual(retry.disabled, false);
		assert.ok(container.textContent?.includes("Couldn't send this response: ipc closed"));
		retry.click();
		assert.deepStrictEqual(responded, ['client-call', 'client-call']);

		renderFold({ ...pending, respondFailure: { retryable: false, error: 'gone' } });
		assert.strictEqual(container.querySelector('.conversation-process-fold-tool-respond'), null);
		assert.ok(container.textContent?.includes("Couldn't send this response: gone"));
		template.disposables.dispose();
	});

	test('a standalone respondable client-tool fallback stays read-only without a response CTA', () => {
		const responded: string[] = [];
		const renderer = renderSeat(() => { }, undefined, turn => responded.push(turn.id));
		const container = document.createElement('div');
		const template = renderer.renderTemplate(container);
		renderer.renderElement(node({ id: 'client-fallback', kind: 'tool', text: 'Pick a file', toolName: 'clientPick', toolStatus: 'pending', respondable: true }), 0, template);
		assert.strictEqual(container.querySelector('.conversation-process-fold-tool-respond'), null);
		assert.deepStrictEqual(responded, []);
		template.disposables.dispose();
	});
});

