				supported: true,
				reason: '',
				branch: 'main',
				changeCount: 1,
			}),
			readGitFileDiff: async () => {
				diffCalls += 1;
				if (diffCalls === 1) {
					await lateGate;
					throw new Error('late-boom');
				}
				return { supported: false, reason: '', path: 'src/a.ts', unifiedDiff: '' };
