	function createLiveScmService(resource: URI, liveGroupId: string): ISCMService {
		const group = {
			id: liveGroupId,
			label: liveGroupId === 'index' ? 'Staged Changes' : 'Changes',
			resources: [] as ISCMResource[],
		};
		const scmResource = {
