		instantiationService.stubInstance(CodeEditorWidget, {
			setModel() { },
			layout() { },
			focus() { },
			dispose() { },
			getModel() { return null; },
		} as unknown as CodeEditorWidget);
		instantiationService.stub(IEditorProgressService, {
			show: () => emptyProgressRunner,
